contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint val, address logAddr) public payable {
        c.Initialized(); if (__ESBMC_reverted()) return;

        bool revertedSetMinSum;
        c.SetMinSum(val); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedSetMinSum = true;
        } else {
            revertedSetMinSum = false;
        }

        assert(revertedSetMinSum);
    }

    receive() external payable {}
}

